@asynccontextmanager
async def lifespan(app: FastAPI):
    """Application lifespan - initialize on startup."""
    global config, model_gateway

    config = get_config()

    # Set log level
    log_level = getattr(logging, config.log_level.upper(), logging.INFO)
    logging.getLogger().setLevel(log_level)

    # Initialize model gateway
    model_gateway = create_model_gateway(config)

    logger.info(f"SAK Router starting on port {config.port}")
    logger.info(f"Session Manager URL: {config.session_manager_url}")
    logger.info(f"Artifact Assembler URL: {config.artifact_assembler_url}")
    logger.info(f"Default model provider: {config.default_provider}")

    yield

    logger.info("SAK Router shutting down")


