async def orchestrate(pipeline_name: str, request: Request):
    """
    Execute a pipeline and stream the response.

    Returns an SSE stream with events:
    - step: Pipeline step completion
    - chunk: LLM response chunk
    - warning: Non-fatal issues
    - error: Fatal errors
    - done: Pipeline completion
    """
    if loader is None or executor is None:
        raise HTTPException(status_code=500, detail="Server not initialized")

    # Get pipeline
    pipeline = loader.get(pipeline_name)
    if pipeline is None:
        raise HTTPException(
            status_code=404,
            detail={
                "error": {
                    "code": "pipeline_not_found",
                    "message": f"Pipeline '{pipeline_name}' not found",
                }
            },
        )

    # Parse request body
    try:
        inputs = await request.json()
    except Exception:
        inputs = {}

    # Apply defaults
    inputs = apply_defaults(pipeline, inputs)

    # Validate inputs
    errors = validate_inputs(pipeline, inputs)
    if errors:
        raise HTTPException(
            status_code=400,
            detail={
                "error": {
                    "code": "invalid_request",
                    "message": "Invalid inputs",
                    "details": {"errors": errors},
                }
            },
        )

    async def event_generator() -> AsyncGenerator[dict[str, str], None]:
        """Generate SSE events from pipeline execution."""
        async for event in executor.execute(pipeline, inputs):
            if isinstance(event, StepEvent):
                yield {
                    "event": "step",
                    "data": event.model_dump_json(exclude_none=True),
                }
            elif isinstance(event, ChunkEvent):
                yield {
